'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { cn } from '../lib/utils'; // optional utility to combine classes

const navItems = [
  { label: 'Dashboard', icon: '📊', href: '/dashboard' },
  { label: 'Wallet', icon: '👛', href: '/wallet' },
  { label: 'Swap', icon: '🔁', href: '/swap' },
  { label: 'Transactions', icon: '📜', href: '/transactions' },
  { label: 'Profile', icon: '👤', href: '/profile' },
];

export const Sidebar = () => {
  const pathname = usePathname();

  return (
    <aside className="w-60 hidden md:flex flex-col bg-gray-800 border-r border-gray-700 p-5 sticky top-0 h-screen">
      <nav className="flex-1">
        <ul className="space-y-3">
          {navItems.map((item) => {
            const isActive = pathname === item.href;
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className={cn(
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors duration-200',
                    isActive
                      ? 'bg-yellow-500 text-black'
                      : 'text-gray-300 hover:bg-gray-700 hover:text-yellow-400'
                  )}
                >
                  <span className="text-lg">{item.icon}</span>
                  {item.label}
                </Link>
              </li>
            );
          })}
        </ul>
      </nav>
      <div className="text-xs text-gray-500 mt-10">© {new Date().getFullYear()} CryptoXchange</div>
    </aside>
  );
};
